const $=s=>document.querySelector(s);let sport='Cricket';
function renderTeams(){const year=Number($('#season').value),index=year-2024;const list=teams.filter(t=>t.sport===sport&&(!$('#kotte-only').checked||t.local));$('#team-count').textContent=`${list.length} team${list.length===1?'':'s'} · ${year}`;$('#team-grid').innerHTML=list.length?list.map(t=>`<article class="team-card"><div class="team-top"><span class="crest">${t.initials}</span><span>${t.place}</span></div><h3>${t.name}</h3><span class="category">${t.category}</span><div class="level">${t.levels[index]}</div><p class="milestone">${t.results[index]}</p><button class="card-button" data-team="${teams.indexOf(t)}">View season journey <span>↗</span></button></article>`).join(''):`<div class="empty"><span class="number">${sport.toUpperCase()} · PROGRAMME FOCUS</span><h3>${sport==='Football'?'Building the next pathway.':'More stories to come.'}</h3><p>${sport==='Football'?'The report names university-affiliated national football players, but provides no Kotte youth football team results.':sport==='Volleyball'?'Volleyball for men and women is part of our programme focus. The supplied report contains no volleyball team records.':'No team records match this location filter.'}</p><p class="small">Team names, competition levels and results will appear here when supplied.</p></div>`;document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>showTeam(Number(b.dataset.team)));}
function renderAthletes(){const q=$('#athlete-search').value.toLowerCase().trim();const list=athletes.filter(a=>`${a.name} ${a.school} ${a.sport}`.toLowerCase().includes(q));$('#athlete-grid').innerHTML=list.length?list.map(a=>`<article class="athlete"><div class="initials" aria-hidden="true">${a.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</div><h3>${a.name}</h3><div class="school">${a.school}</div><span class="tag">${a.tag}</span><p class="achievement">${a.achievement}</p><button class="card-button" data-athlete="${athletes.indexOf(a)}">Follow the journey <span>↗</span></button></article>`).join(''):'<p class="empty">No athletes match your search. Try another name, school or sport.</p>';document.querySelectorAll('[data-athlete]').forEach(b=>b.onclick=()=>showAthlete(Number(b.dataset.athlete)));}
function openDetail(html){$('#dialog-content').innerHTML=html;$('#detail').showModal();}
function source(page){return `<p class="source-note">Reported in the supplied 2024–2026 dossier, page ${page}. Not independently verified.</p><a class="text-link" href="sports-report.pdf#page=${page}" target="_blank" rel="noopener">Open source report ↗</a>`;}
function showTeam(i){const t=teams[i];openDetail(`<span class="eyebrow">${t.sport.toUpperCase()} / ${t.place.toUpperCase()}</span><h2>${t.name}</h2><p>${t.category}</p><ol class="timeline">${t.levels.map((l,j)=>`<li><b>${2024+j} · ${l}</b><br>${t.results[j]}</li>`).join('')}</ol><div class="support-note">Capital of Hope SL support: not documented in the supplied report.</div>${source(t.page)}`);}
function showAthlete(i){const a=athletes[i];openDetail(`<span class="eyebrow">${a.sport.toUpperCase()} / ATHLETE JOURNEY</span><h2>${a.name}</h2><p>${a.school}</p><ul class="timeline">${a.events.map(e=>`<li>${e}</li>`).join('')}</ul><div class="support-note"><b>Project support record</b><p>No assistance from Capital of Hope SL is documented in the supplied report. Kotte residence is not confirmed by school affiliation.</p></div>${source(a.page)}`);}
document.querySelectorAll('[data-sport]').forEach(b=>b.onclick=()=>{sport=b.dataset.sport;document.querySelectorAll('[data-sport]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});renderTeams();});$('#season').onchange=renderTeams;$('#kotte-only').onchange=renderTeams;$('#athlete-search').oninput=renderAthletes;$('#close-dialog').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});renderTeams();renderAthletes();

const menuToggle=document.querySelector('.menu-toggle'); menuToggle.addEventListener('click',()=>{const expanded=menuToggle.getAttribute('aria-expanded')==='true';menuToggle.setAttribute('aria-expanded',String(!expanded));document.querySelector('#main-nav').classList.toggle('open',!expanded);});document.querySelectorAll('#main-nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#main-nav').classList.remove('open');menuToggle.setAttribute('aria-expanded','false');}));
